router5.get("/:businessId", async (req, res) => {
  try {
    const { businessId } = req.params;
    const paged = String(req.query.paged ?? "") === "1";
    if (paged) {
      const requestedLimit = Number(req.query.limit);
      const limit = Number.isFinite(requestedLimit) ? Math.min(300, Math.max(20, Math.trunc(requestedLimit))) : 120;
      const cursor = String(req.query.cursor ?? "").trim();
      let query = db.collection(`negocios/${businessId}/ventas`).orderBy("fecha", "desc").limit(limit + 1);
      if (cursor) {
        const cursorSnap = await db.collection(`negocios/${businessId}/ventas`).doc(cursor).get();
        if (cursorSnap.exists) {
          query = query.startAfter(cursorSnap);
        }
      }
      const snapshot2 = await query.get();
      const hasMore = snapshot2.docs.length > limit;
      const docs = hasMore ? snapshot2.docs.slice(0, limit) : snapshot2.docs;
      const sales2 = docs.map((doc) => {
        const data = doc.data();
        return {
          id: doc.id,
          ...data,
          ventaLabel: resolveSaleLabel(data)
        };
      });
      const enriched2 = await enrichSales(businessId, sales2);
      const nextCursor = hasMore && docs.length > 0 ? docs[docs.length - 1].id : null;
      return res.json({ items: enriched2, nextCursor, hasMore });
    }
    const snapshot = await db.collection(`negocios/${businessId}/ventas`).orderBy("fecha", "desc").get();
    const sales = snapshot.docs.map((doc) => {
      const data = doc.data();
      return {
        id: doc.id,
        ...data,
        ventaLabel: resolveSaleLabel(data)
      };
    });
    const enriched = await enrichSales(businessId, sales);
    res.json(enriched);
  } catch (error) {
    console.error("Error fetching sales:", error);
    res.status(500).json({ error: "Error fetching sales" });
  }
});
async function maybeCreateCompromisoPago(businessId, params) {
  if (params.saldoPendiente <= 0 || !params.clienteId) return null;
  const compromiso = parseCompromisoInput(params.body.compromisoPago);
  if (!compromiso) return null;
  return createCompromisoPago(businessId, {
    clienteId: params.clienteId,
    origenTipo: params.origenTipo,
    origenId: params.origenId,
    referenciaLabel: params.referenciaLabel,
    montoTotal: params.saldoPendiente,
    compromiso,
    pedidoId: params.pedidoId,
    ventaId: params.ventaId
  });
}
