router5.post("/:businessId/:ventaId/confirm", async (req, res) => {
  try {
    const { businessId, ventaId } = req.params;
    let result;
    try {
      result = await confirmMostradorSaleDraft(businessId, ventaId, req.body);
    } catch (err) {
      const message = err instanceof Error ? err.message : "";
      if (message === "SALE_NOT_FOUND") {
        return res.status(404).json({ error: "Venta no encontrada." });
      }
      if (message === "NOT_DRAFT") {
        return res.status(400).json({ error: "Solo se pueden confirmar ventas en borrador." });
      }
      if (message === "EMPTY_DRAFT") {
        return res.status(400).json({ error: "Agreg\xE1 al menos un producto antes de confirmar." });
      }
      if (message === "CLIENT_REQUIRED") {
        return res.status(400).json({ error: "Seleccion\xE1 un cliente para la venta." });
      }
      if (message === "INVALID_AMOUNT") {
        return res.status(400).json({ error: "El monto cobrado supera el total de la venta." });
      }
      if (message.includes("Stock insuficiente") || message.includes("no existe")) {
        return res.status(400).json({ error: message });
      }
      throw err;
    }
    await logActivityFromRequest(req, businessId, {
      module: "sales",
      action: "confirm",
      entityType: "venta",
      entityId: result.id,
      entityLabel: result.ventaLabel,
      summary: `Confirm\xF3 venta mostrador #${result.ventaLabel} \xB7 $${result.total}`
    });
    res.status(200).json(result);
  } catch (error) {
    console.error("Error confirming sale:", error);
    res.status(500).json({ error: "Error confirming sale" });
  }
});
