// backend/billing/mp-webhook-parse.ts
function parseMercadoPagoWebhook(input) {
  const query = input.query ?? {};
  const body = input.body ?? {};
  const rawTopic = String(
    query.topic ?? query.type ?? body.type ?? body.topic ?? ""
  ).trim().toLowerCase();
  const topic = rawTopic === "payment" || rawTopic === "subscription_preapproval" || rawTopic === "preapproval" || rawTopic === "subscription_authorized_payment" || rawTopic === "authorized_payment" || rawTopic === "merchant_order" ? rawTopic === "preapproval" ? "subscription_preapproval" : rawTopic === "authorized_payment" ? "subscription_authorized_payment" : rawTopic : rawTopic ? "unknown" : "payment";
  const data = body.data ?? {};
  const dataId = String(
    query["data.id"] ?? query.id ?? data.id ?? body.id ?? ""
  ).trim();
  return { topic, dataId };
}

// backend/billing/mp-webhooks.ts
function eventRef(key) {
  return db.doc(`plataforma/mp_webhook_events/items/${key}`);
}
function paymentRef(businessId, paymentId) {
  return db.doc(`negocios/${businessId}/mp_payments/${paymentId}`);
}
async function claimWebhookEvent(topic, dataId) {
  const key = webhookIdempotencyKey(topic, dataId);
  const ref2 = eventRef(key);
  const existing = await ref2.get();
  if (existing.exists && existing.data()?.processed === true) {
    return { key, duplicate: true };
  }
  await ref2.set(
    {
      key,
      topic,
      dataId,
      processed: false,
      receivedAt: (/* @__PURE__ */ new Date()).toISOString()
    },
    { merge: true }
  );
  return { key, duplicate: false };
}
async function markWebhookProcessed(key, extra) {
  await eventRef(key).set(
    {
      processed: true,
      processedAt: (/* @__PURE__ */ new Date()).toISOString(),
      ...extra
    },
    { merge: true }
  );
}
async function saveMpPayment(row) {
  const id2 = String(row.paymentId || "").trim();
  const businessId = String(row.businessId || "").trim();
  if (!id2 || !businessId) return false;
  const ref2 = paymentRef(businessId, id2);
  const existing = await ref2.get();
  if (existing.exists) return false;
  await ref2.set({
    paymentId: id2,
    preapprovalId: row.preapprovalId ?? null,
    status: row.status,
    grossAmount: row.grossAmount,
    feeAmount: row.feeAmount ?? null,
    netAmount: row.netAmount ?? null,
    currency: row.currency ?? null,
    date: row.date,
    businessId,
    topic: row.topic,
    country: row.country ?? null,
    createdAt: (/* @__PURE__ */ new Date()).toISOString()
  });
  return true;
}
async function listMpPaymentsInPeriod(businessId, period) {
  const start = `${period}-01`;
  const [year, month] = period.split("-").map(Number);
  const endDate = new Date(Date.UTC(year, month, 1));
  const end = endDate.toISOString().slice(0, 10);
  const snap = await db.collection(`negocios/${businessId}/mp_payments`).where("date", ">=", start).where("date", "<", end).get();
  return snap.docs.map((doc) => doc.data());
}

// shared/profitability.ts
init_usage_cost();
function localAmountToUsd(amount, currency, rates) {
  const n = Math.max(0, Number(amount) || 0);
  if (currency === "ARS") {
    const fx2 = Math.max(1, Number(rates.arsPerUsd) || 1400);
    return n / fx2;
  }
  const fx = Math.max(1, Number(rates.uyuPerUsd) || 40);
  return n / fx;
}
function marginPct(incomeUsd, costUsd) {
  if (!(incomeUsd > 0)) return null;
  return Math.round((incomeUsd - costUsd) / incomeUsd * 1e3) / 10;
}
function buildProfitability(input) {
  const incomeUsdEstimated = roundUsd(
    localAmountToUsd(input.incomeTotal, input.currency, input.fx)
  );
  const costs = [
    {
      code: "gemini",
      label: "Gemini",
      usd: roundUsd(input.geminiUsd),
      source: "real"
    },
    {
      code: "whatsapp_meta",
      label: "WhatsApp Meta",
      usd: roundUsd(input.whatsappMetaUsd),
      source: "estimated"
    },
    {
      code: "mercadopago",
      label: "Mercado Pago",
      usd: roundUsd(input.mercadoPagoUsd),
      source: input.mercadoPagoSource
    },
    {
      code: "firebase_gcp",
      label: "Firebase/GCP",
      usd: roundUsd(input.firebaseUsd),
      source: "estimated"
    },
    {
      code: "other",
      label: "Otros",
      usd: roundUsd(input.otherUsd),
      source: "estimated"
    }
  ].filter((row) => row.usd > 0 || row.code === "gemini" || row.code === "whatsapp_meta");
  const costUsdReal = roundUsd(
    costs.filter((row) => row.source === "real").reduce((sum, row) => sum + row.usd, 0)
  );
  const costUsdEstimated = roundUsd(
    costs.filter((row) => row.source === "estimated").reduce((sum, row) => sum + row.usd, 0)
  );
  const costUsd = roundUsd(costUsdReal + costUsdEstimated);
  const profitUsd = roundUsd(incomeUsdEstimated - costUsd);
  return {
    income: {
      currency: input.currency,
      lines: input.incomeLines,
      total: input.incomeTotal,
      totalUsdEstimated: incomeUsdEstimated
    },
    costs,
    costUsd,
    costUsdReal,
    costUsdEstimated,
    result: {
      profitUsd,
      marginPct: marginPct(incomeUsdEstimated, costUsd),
      incomeUsdEstimated
    }
  };
}

// backend/billing/platform-profitability.ts
init_usage_cost();
async function attachProfitability(rows, period) {
  const catalog = await getCommercialCatalog();
  const fx = {
    uyuPerUsd: catalog.finops?.uyuPerUsd ?? 40,
    arsPerUsd: catalog.finops?.arsPerUsd ?? 1400
  };
  const firebaseMonthly = catalog.finops?.firebaseMonthlyUsd ?? 25;
  const otherMonthly = catalog.finops?.otherMonthlyUsd ?? 0;
  const mpFeePercent = catalog.finops?.mpFeePercent ?? 4.99;
  const totalAi = rows.reduce((sum, row) => sum + (row.ai?.used || 0), 0) || 1;
  const enriched = await Promise.all(
    rows.map(async (row) => {
      const quote = row.quote;
      const currency = quote?.rates.currency ?? "UYU";
      const incomeLines = (quote?.lines ?? []).map((line) => ({
        code: line.code === "BASE" ? "plan" : line.code === "ERP_EXTRA" ? "erp_extra" : line.code === "WA_EXTRA" ? "wa_extra" : line.code === "DISCOUNT" ? "discount" : line.code === "CUSTOM" ? "custom" : "addons",
        label: line.label,
        amount: line.amount
      }));
      const incomeTotal = quote?.total ?? row.expectedMonthly ?? 0;
      const incomeUsd = localAmountToUsd(incomeTotal, currency, fx);
      let mpRealUsd = 0;
      let mpHasReal = false;
      if (row.businessId) {
        try {
          const payments = await listMpPaymentsInPeriod(row.businessId, period);
          const fees = payments.reduce((sum, payment) => sum + (Number(payment.feeAmount) || 0), 0);
          if (fees > 0) {
            mpRealUsd = localAmountToUsd(fees, payments[0]?.currency || currency, fx);
            mpHasReal = true;
          }
        } catch (error) {
          console.warn("[profitability] mp payments", row.businessId, error);
        }
      }
      const mpEstimatedUsd = incomeUsd * (mpFeePercent / 100);
      const firebaseUsd = firebaseMonthly * ((row.ai?.used || 0) / totalAi);
      const otherUsd = otherMonthly * ((row.ai?.used || 0) / totalAi);
      const profit = buildProfitability({
        currency,
        incomeLines,
        incomeTotal,
        geminiUsd: row.geminiUsd || 0,
        whatsappMetaUsd: row.whatsappUsd || 0,
        mercadoPagoUsd: mpHasReal ? mpRealUsd : mpEstimatedUsd,
        mercadoPagoSource: mpHasReal ? "real" : "estimated",
        firebaseUsd,
        otherUsd,
        fx
      });
      return {
        ...row,
        incomePlan: quote?.rates.baseAmount ?? 0,
        extraErpCost: quote?.extraErpCost ?? row.extraErpCost ?? 0,
        extraWhatsappCost: quote?.extraWhatsappCost ?? row.extraWhatsappCost ?? 0,
        addonCost: quote?.addonTotal ?? 0,
        profitability: profit
      };
    })
  );
  const totals = enriched.reduce(
    (acc, row) => {
      const p = row.profitability;
      acc.incomeUsd += p.result.incomeUsdEstimated;
      acc.costUsd += p.costUsd;
      acc.costUsdReal += p.costUsdReal;
      acc.costUsdEstimated += p.costUsdEstimated;
      acc.profitUsd += p.result.profitUsd;
      for (const cost of p.costs) {
        acc.byVendor[cost.code] = (acc.byVendor[cost.code] || 0) + cost.usd;
      }
      return acc;
    },
    {
      incomeUsd: 0,
      costUsd: 0,
      costUsdReal: 0,
      costUsdEstimated: 0,
      profitUsd: 0,
      byVendor: {}
    }
  );
  return {
    rows: enriched,
    totals: {
      incomeUsdEstimated: roundUsd(totals.incomeUsd),
      costUsd: roundUsd(totals.costUsd),
      costUsdReal: roundUsd(totals.costUsdReal),
      costUsdEstimated: roundUsd(totals.costUsdEstimated),
      profitUsd: roundUsd(totals.profitUsd),
      marginPct: totals.incomeUsd > 0 ? Math.round((totals.incomeUsd - totals.costUsd) / totals.incomeUsd * 1e3) / 10 : null,
      byVendor: Object.fromEntries(
        Object.entries(totals.byVendor).map(([key, value]) => [key, roundUsd(value)])
      ),
      firebaseNote: "Firebase/GCP es un estimado mensual atribuido por acciones. No es un costo exacto de la factura de Google."
    }
  };
}

