function helpSectionHasOperationalTool(sectionId, availableToolNames) {
  const set = availableToolNames instanceof Set ? availableToolNames : new Set(availableToolNames);
  const required = HELP_SECTION_OPERATIONAL_TOOLS[sectionId] ?? [];
  return required.some((name) => set.has(name));
}

